import numpy as np

grid = np.array([[int(x) for x in line.split()] for line in input_str.strip().split('\n')])
h_lines = np.array([6, 17, 19])
v_lines = np.array([4, 13, 24, 28])

# For each cell NOT on a divider line, let's count how many sides touch a divider
divider_adj = np.zeros((22, 29), dtype=int)
for i in range(22):
    for j in range(29):
        if i in h_lines or j in v_lines:
            continue

        adj = 0
        if i > 0 and (i-1) in h_lines:
            adj += 1
        if i < 21 and (i+1) in h_lines:
            adj += 1
        if j > 0 and (j-1) in v_lines:
            adj += 1
        if j < 28 and (j+1) in v_lines:
            adj += 1

        divider_adj[i, j] = adj

# Count of cells with each adjacency value
counts = {}
for adj in divider_adj.flatten():
    counts[adj] = counts.get(adj, 0) + 1

print("Divider adjacency counts:")
for k, v in sorted(counts.items()):
    print(f"  Adj={k}: {v} cells")

# Unique non-zero counts
print(f"\nNon-zero adj counts: {sorted(set(filter(None, divider_adj.flatten())))}")

